options.getOption:
/**
 * Chicago-style stacked wind rose for Business Charts (volkovlabs-echarts-panel).
 * Pairing: AWS (masthead) + one direction series.
 *
 * MODE is replaced per dashboard:
 *   twd — compass-true, N up (WeatherTWD / at anchor)
 *   awa — bow-relative, 0° up (WeatherAWA / underway)
 */
const MODE = 'awa';

const BINS = [
  { name: '2.0–4.9 kn', lo: 2.0, hi: 5.0, color: '#1d3557' },
  { name: '5.0–6.9 kn', lo: 5.0, hi: 7.0, color: '#2a9d8f' },
  { name: '7.0–9.9 kn', lo: 7.0, hi: 10.0, color: '#8ac926' },
  { name: '10.0–14.9 kn', lo: 10.0, hi: 15.0, color: '#ffd166' },
  { name: '15.0–19.9 kn', lo: 15.0, hi: 20.0, color: '#f4a261' },
  { name: '20.0+ kn', lo: 20.0, hi: Infinity, color: '#e63946' },
];
const N = 36;
const DEGS = Array.from({ length: N }, (_, i) => i * 10);
const CALM_MAX = 2.0;

const theme = (context.grafana && context.grafana.theme) || {};
const isDark = theme.isDark !== false;
const textColor = (theme.colors && theme.colors.text && theme.colors.text.primary) || (isDark ? '#e8e8e8' : '#1a1a1a');
const muted = (theme.colors && theme.colors.text && theme.colors.text.secondary) || (isDark ? 'rgba(232,232,232,0.65)' : 'rgba(26,26,26,0.55)');
const gridColor = isDark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.18)';

function fieldValues(field) {
  if (!field) {
    return [];
  }
  const v = field.values;
  if (!v) {
    return [];
  }
  if (v.buffer) {
    return Array.from(v.buffer);
  }
  if (typeof v.toArray === 'function') {
    return v.toArray();
  }
  return Array.from(v);
}

function findField(series, names) {
  const lower = names.map((n) => n.toLowerCase());
  return (series.fields || []).find((f) => lower.indexOf(String(f.name || '').toLowerCase()) >= 0);
}

function emptyChart(msg) {
  return {
    backgroundColor: 'transparent',
    title: {
      text: msg,
      left: 'center',
      top: 'middle',
      textStyle: { color: muted, fontSize: 14, fontWeight: 'normal' },
    },
  };
}

const seriesList = (context.panel.data && context.panel.data.series) || [];
if (!seriesList.length) {
  return emptyChart(MODE === 'awa' ? 'No AWA/AWS in range' : 'No TWD/AWS in range');
}

const s0 = seriesList[0];
const dirField = findField(s0, ['wind_direction', 'direction']);
const spdField = findField(s0, ['wind_speed', 'speed']);
if (!dirField || !spdField) {
  return emptyChart('Wind rose needs wind_direction + wind_speed');
}

const dirs = fieldValues(dirField);
const spds = fieldValues(spdField);
const n = Math.min(dirs.length, spds.length);
if (!n) {
  return emptyChart(MODE === 'awa' ? 'No AWA/AWS in range' : 'No TWD/AWS in range');
}

const counts = BINS.map(() => Array(N).fill(0));
let calm = 0;
let used = 0;
for (let i = 0; i < n; i++) {
  const d = Number(dirs[i]);
  const v = Number(spds[i]);
  if (!isFinite(d) || !isFinite(v)) {
    continue;
  }
  used += 1;
  if (v < CALM_MAX) {
    calm += 1;
    continue;
  }
  const deg = ((d % 360) + 360) % 360;
  const sector = Math.floor(((deg + 5) % 360) / 10);
  for (let b = 0; b < BINS.length; b++) {
    if (v >= BINS[b].lo && v < BINS[b].hi) {
      counts[b][sector] += 1;
      break;
    }
  }
}

if (!used) {
  return emptyChart(MODE === 'awa' ? 'No AWA/AWS in range' : 'No TWD/AWS in range');
}

const toPct = (c) => (100.0 * c) / used;
const calmPct = toPct(calm);
const binPct = counts.map((row) => row.map(toPct));
const petalTotal = Array(N).fill(0);
for (let b = 0; b < BINS.length; b++) {
  for (let k = 0; k < N; k++) {
    petalTotal[k] += binPct[b][k];
  }
}

function axisLabel(deg) {
  if (MODE === 'awa') {
    if (deg === 0) {
      return 'Bow';
    }
    if (deg === 90) {
      return 'Stbd';
    }
    if (deg === 180) {
      return 'Aft';
    }
    if (deg === 270) {
      return 'Port';
    }
    return String(deg);
  }
  if (deg === 0) {
    return 'N';
  }
  if (deg === 90) {
    return 'E';
  }
  if (deg === 180) {
    return 'S';
  }
  if (deg === 270) {
    return 'W';
  }
  if (deg === 40) {
    return 'NE';
  }
  if (deg === 130) {
    return 'SE';
  }
  if (deg === 220) {
    return 'SW';
  }
  if (deg === 310) {
    return 'NW';
  }
  return String(deg);
}

const polarSeries = BINS.map((bin, b) => ({
  type: 'bar',
  name: bin.name,
  coordinateSystem: 'polar',
  stack: 'wind',
  data: binPct[b],
  itemStyle: { color: bin.color },
  emphasis: { focus: 'series' },
  barCategoryGap: '8%',
}));

polarSeries.push({
  type: 'bar',
  name: '_labels',
  coordinateSystem: 'polar',
  stack: 'wind',
  data: Array(N).fill(0),
  itemStyle: { color: 'transparent' },
  silent: true,
  tooltip: { show: false },
  legendHoverLink: false,
  label: {
    show: true,
    position: 'end',
    distance: 6,
    color: muted,
    fontSize: 9,
    formatter: (p) => {
      const t = petalTotal[p.dataIndex];
      return t >= 0.8 ? t.toFixed(1) + '%' : '';
    },
  },
});

return {
  backgroundColor: 'transparent',
  animation: false,
  legend: {
    bottom: 0,
    left: 'center',
    data: BINS.map((b) => b.name),
    textStyle: { color: textColor, fontSize: 11 },
    itemWidth: 12,
    itemHeight: 8,
  },
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      if (!p || p.seriesName === '_labels') {
        return '';
      }
      const deg = DEGS[p.dataIndex];
      const dir = axisLabel(deg);
      const val = typeof p.value === 'number' ? p.value.toFixed(2) : p.value;
      return dir + ' (' + deg + '°)<br/>' + p.seriesName + ': ' + val + '%';
    },
  },
  polar: {
    radius: ['24%', '70%'],
    center: ['50%', '46%'],
  },
  angleAxis: {
    type: 'category',
    data: DEGS,
    startAngle: 90,
    clockwise: true,
    axisLine: { lineStyle: { color: gridColor } },
    axisTick: { show: true, lineStyle: { color: gridColor } },
    splitLine: { show: true, lineStyle: { color: gridColor } },
    axisLabel: {
      color: textColor,
      fontSize: 10,
      formatter: axisLabel,
    },
  },
  radiusAxis: {
    type: 'value',
    min: 0,
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: {
      color: muted,
      fontSize: 10,
      formatter: '{value}%',
    },
    splitLine: { lineStyle: { color: gridColor } },
  },
  series: polarSeries,
  graphic: [
    {
      type: 'text',
      left: 'center',
      top: '43%',
      style: {
        text: 'Calm:\n' + calmPct.toFixed(2) + '%',
        fill: textColor,
        font: 'bold 13px sans-serif',
        align: 'center',
        textAlign: 'center',
      },
    },
  ],
};
